css:
/* 场间 FIELD NOTES · 概念样板
   <!-- muse:allow hard-2px-border: 本作品取「展场平面图 + 展签」的物质性，
        2px 炭墨硬线是它的形式语言（图纸描边、分区边框），非无意厚边框 -->
   <!-- muse:allow grain-overlay: Grain 施加在 fixed inset-0 pointer-events-none 独立层，
        isolation:isolate、z-index:1，压在内容之下，不参与滚动重绘 -->
*/
:root{
  --paper:#F5F1E9; --paper-2:#EDE7DA; --paper-3:#E3DBCB;
  --ink:#1A1714; --ink-2:#57504A; --ink-3:#7C736A;
  --line:#CFC5B2; --line-soft:#DED6C6;
  --vermil:#C2321F; --vermil-d:#9E2718; --ok:#2E6B4F;
  --r:2px; --ease:cubic-bezier(0.16,1,0.3,1);
  --mono:'Aeonik Mono','Space Mono','IBM Plex Mono','Noto Sans Mono',Menlo,ui-monospace,monospace;
  --sans:'Inter','Helvetica Neue','PingFang SC','Noto Sans SC','Source Han Sans SC',sans-serif;
  --serif:'Songti SC','Noto Serif SC',Georgia,serif;
}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);
  font-size:16px;line-height:1.6;-webkit-font-smoothing:antialiased;overflow-x:hidden}
body::before{content:"";position:fixed;inset:0;z-index:0;pointer-events:none;
  background-image:linear-gradient(rgba(26,23,20,.045) 1px,transparent 1px),
    linear-gradient(90deg,rgba(26,23,20,.045) 1px,transparent 1px);
  background-size:24px 24px}
body::after{content:"";position:fixed;inset:0;z-index:1;pointer-events:none;isolation:isolate;opacity:.5;
  background-image:radial-gradient(rgba(26,23,20,.055) .6px,transparent .6px);background-size:3px 3px}
.wrap{position:relative;z-index:2}
a{color:inherit}
button{font:inherit;color:inherit}
[hidden]{display:none !important}
.skip{position:absolute;left:-9999px;top:0;z-index:60;background:var(--ink);color:var(--paper);
  padding:12px 20px;font-family:var(--mono);font-size:13px}
.skip:focus{left:16px;top:16px}
:focus-visible{outline:3px solid var(--vermil);outline-offset:2px;border-radius:1px}

/* ticker */
.ticker{background:var(--ink);color:var(--paper);border-bottom:2px solid var(--ink)}
.ticker__inner{max-width:1440px;margin:0 auto;padding:9px 24px;display:flex;align-items:center;
  gap:12px;flex-wrap:wrap;font-family:var(--mono);font-size:12px;letter-spacing:.06em}
.ticker__dot{width:7px;height:7px;border-radius:50%;background:var(--vermil);flex:none;
  animation:pulse 2.4s var(--ease) infinite}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.35}}
.ticker__sep{width:1px;height:12px;background:rgba(245,241,233,.32);flex:none}

/* topbar */
.topbar{position:sticky;top:0;z-index:20;background:var(--paper);border-bottom:2px solid var(--ink);
  display:flex;align-items:center;gap:24px;padding:10px 24px;max-width:1440px;margin:0 auto}
@supports (backdrop-filter:blur(8px)){.topbar{background:rgba(245,241,233,.9);backdrop-filter:blur(10px)}}
.brand{display:flex;align-items:center;gap:10px;text-decoration:none;flex:none}
.brand__mark{width:34px;height:34px;display:grid;place-items:center;background:var(--vermil);
  color:var(--paper);border:2px solid var(--ink);border-radius:var(--r);font-size:17px;font-weight:700;line-height:1}
.brand__txt{display:flex;flex-direction:column;line-height:1.15}
.brand__name{font-size:16px;font-weight:700;letter-spacing:.14em}
.brand__en{font-family:var(--mono);font-size:10px;letter-spacing:.2em;color:var(--ink-3)}
.topnav{display:flex;gap:20px;margin-left:8px}
.topnav a{text-decoration:none;font-size:14px;min-height:44px;display:flex;align-items:center;
  border-bottom:2px solid transparent;transition:border-color .18s var(--ease)}
.topnav a:hover{border-bottom-color:var(--ink)}
.topbar__right{margin-left:auto;display:flex;align-items:center;gap:16px}
.clock{font-family:var(--mono);font-size:12px;letter-spacing:.08em;color:var(--ink-3);
  font-variant-numeric:tabular-nums}
.dockbtn{display:flex;align-items:center;gap:8px;background:var(--paper);border:2px solid var(--ink);
  border-radius:var(--r);padding:9px 14px;min-height:44px;cursor:pointer;font-size:14px;
  transition:transform .14s var(--ease),background-color .14s var(--ease)}
.dockbtn:hover{background:var(--paper-3);transform:translateY(-2px)}
.dockbtn:active{transform:translateY(0)}
.dockbtn__n{font-family:var(--mono);font-size:12px;font-weight:700;background:var(--vermil);
  color:var(--paper);min-width:20px;text-align:center;padding:1px 5px;border-radius:2px;
  font-variant-numeric:tabular-nums}

/* hero */
.hero{max-width:1440px;margin:0 auto;padding:40px 24px 0}
.hero__grid{display:grid;grid-template-columns:minmax(0,1.22fr) minmax(0,1fr);gap:48px;align-items:start}
.eyebrow{font-family:var(--mono);font-size:12px;letter-spacing:.2em;color:var(--ink-3);
  margin:0 0 20px;padding-bottom:8px;border-bottom:1px solid var(--line)}
.hero__title{margin:0;font-weight:700;line-height:.9;letter-spacing:.04em;
  font-size:clamp(80px,13vw,176px);display:flex;gap:.04em}
.hero__title span{display:inline-block}
.t1{color:var(--ink)}
.t2{color:var(--vermil);text-shadow:3px 3px 0 var(--ink)}
.hero__sub{font-family:var(--mono);font-size:14px;letter-spacing:.14em;margin:14px 0 0}
.hero__sub-cn{font-family:var(--sans);letter-spacing:.02em;color:var(--ink-2);font-size:14px}
.hero__desc{font-size:16px;line-height:1.7;color:var(--ink-2);max-width:34em;margin:20px 0 28px}
.hero__cta{display:flex;gap:16px;flex-wrap:wrap}

.btn{display:inline-flex;align-items:center;gap:8px;border:2px solid var(--ink);border-radius:var(--r);
  padding:12px 22px;min-height:48px;cursor:pointer;text-decoration:none;font-size:15px;font-weight:600;
  background:var(--paper);transition:transform .14s var(--ease),background-color .14s var(--ease),
  color .14s var(--ease)}
.btn--primary{background:var(--vermil);color:#FFF8F4}
.btn--primary:hover{background:var(--vermil-d);transform:translateY(-3px)}
.btn--primary:active{transform:translateY(0)}
.btn--ghost{background:transparent}
.btn--ghost:hover{background:var(--paper-2);transform:translateY(-3px)}
.btn--ghost:active{transform:translateY(0)}
.btn--sm{min-height:44px;padding:9px 16px;font-size:14px}
.btn__arrow{font-family:var(--mono);font-size:15px}

/* plan */
.plan{border:2px solid var(--ink);border-radius:var(--r);background:var(--paper-2);padding:14px;
  box-shadow:8px 8px 0 var(--ink)}
.plan__svg{display:block;width:100%;height:auto}
.plan__cap{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:10px;
  padding-top:10px;border-top:1px solid var(--line);font-family:var(--mono);font-size:12px;
  letter-spacing:.1em;color:var(--ink-3);flex-wrap:wrap}
.plan__cap-r{color:var(--vermil)}

/* daystrip */
.hero__days{margin-top:40px}
.daystrip{display:grid;grid-template-columns:repeat(3,minmax(0,1fr)) minmax(0,1.5fr);
  border:2px solid var(--ink);border-radius:var(--r);overflow:hidden;background:var(--paper-2)}
.daystrip__item{padding:14px 20px;border-right:1px solid var(--line);display:flex;
  flex-direction:column;gap:4px;min-height:44px}
.daystrip__d{font-family:var(--mono);font-size:12px;font-weight:700;color:var(--vermil);letter-spacing:.14em}
.daystrip__t{font-size:15px;font-weight:600}
.daystrip__n{font-family:var(--mono);font-size:12px;color:var(--ink-3);letter-spacing:.04em}
.daystrip__note{padding:14px 20px;background:var(--ink);color:var(--paper);font-size:14px;
  line-height:1.5;display:flex;align-items:center}

/* stage */
.stage{max-width:1440px;margin:72px auto 0;padding:0 24px;
  display:grid;grid-template-columns:minmax(0,206px) minmax(0,1fr) minmax(0,312px);
  gap:0;align-items:start;border-top:2px solid var(--ink)}
.legend{padding:32px 24px 32px 0;border-right:1px solid var(--line)}
.legend__block{margin-bottom:32px}
.legend__h{font-family:var(--mono);font-size:12px;font-weight:700;letter-spacing:.18em;margin:0 0 12px;
  padding-bottom:8px;border-bottom:1px solid var(--line)}
.legend__list{display:flex;flex-direction:column;gap:2px}
.filt{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;
  text-align:left;background:transparent;border:0;border-left:3px solid transparent;padding:11px 12px;
  min-height:44px;cursor:pointer;font-size:14px;
  transition:background-color .16s var(--ease),border-color .16s var(--ease)}
.filt:hover{background:var(--paper-2)}
.filt.is-on{background:var(--paper-2);border-left-color:var(--vermil);font-weight:600}
.filt__n{font-family:var(--mono);font-size:12px;color:var(--ink-3);font-variant-numeric:tabular-nums}
.legend__block--note{border-top:1px solid var(--line);padding-top:20px}
.legend__p{font-size:13.5px;line-height:1.65;color:var(--ink-2);margin:0}
.inline-act{font-weight:600;color:var(--vermil);border-bottom:1.5px solid var(--vermil);white-space:nowrap}
.legend__reset{width:100%;justify-content:center}

/* board */
.board{padding:32px 24px}
.board__head{display:flex;justify-content:space-between;align-items:baseline;gap:16px;
  margin-bottom:8px;flex-wrap:wrap}
.board__h{margin:0;font-size:26px;font-weight:700;letter-spacing:.02em;line-height:1.25}
.board__status{font-family:var(--mono);font-size:12px;color:var(--ink-3);margin:0;letter-spacing:.06em}
.board__colhead{display:grid;grid-template-columns:76px minmax(0,1fr) 132px;gap:16px;
  border-top:2px solid var(--ink);border-bottom:1px solid var(--line);padding:9px 0;
  font-family:var(--mono);font-size:11px;letter-spacing:.16em;color:var(--ink-3)}
.ch--act{text-align:right}

.row{border-bottom:1px solid var(--line)}
.row.is-new{animation:rowIn .34s var(--ease) both}
@keyframes rowIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.row__head{display:grid;grid-template-columns:76px minmax(0,1fr) 132px;gap:16px;align-items:start;padding:20px 0}
.row__no{font-family:var(--mono);font-weight:700;line-height:.9;font-size:40px;color:var(--ink-3);
  letter-spacing:-.02em;font-variant-numeric:tabular-nums;transition:color .2s var(--ease)}
.row.is-open .row__no,.row:hover .row__no{color:var(--vermil)}
.row__body{min-width:0}
.row__tag{display:inline-flex;align-items:center;gap:8px;font-family:var(--mono);font-size:12px;
  letter-spacing:.12em;padding:4px 9px;border:1px solid var(--ink);border-radius:var(--r);
  margin-bottom:10px;background:var(--paper-2)}
.row__tag--talk{background:#E7E0D0}
.row__tag--work{background:#DED6C6}
.row__tagDot{width:6px;height:6px;border-radius:50%;background:var(--vermil);display:inline-block}
.row__title{margin:0 0 8px;font-size:21px;line-height:1.35;font-weight:700;letter-spacing:.01em}
.row__meta{display:flex;flex-wrap:wrap;gap:6px 18px;font-family:var(--mono);font-size:12.5px;
  color:var(--ink-2);letter-spacing:.04em}
.row__meta b{font-weight:700;color:var(--ink);font-variant-numeric:tabular-nums}
.row__acts{display:flex;flex-direction:column;gap:8px}
.row__btn{border:2px solid var(--ink);border-radius:var(--r);background:var(--paper);padding:10px 12px;
  min-height:44px;cursor:pointer;font-size:13.5px;font-weight:600;display:flex;align-items:center;
  justify-content:center;gap:6px;
  transition:transform .14s var(--ease),background-color .14s var(--ease),color .14s var(--ease),
  border-color .14s var(--ease)}
.row__btn:hover{background:var(--ink);color:var(--paper);transform:translateY(-2px)}
.row__btn:active{transform:translateY(0)}
.row__btn--add.is-in{background:var(--ok);border-color:var(--ok);color:#F2F7F4}
.row__btn--add.is-in:hover{background:var(--ink);border-color:var(--ink);color:var(--paper)}
.row__btn span.k{font-family:var(--mono);font-size:12px}
.row__btn[aria-expanded="true"]{background:var(--ink);color:var(--paper)}
.row.has-conflict{border-left:2px solid var(--vermil);margin-left:-2px;padding-left:2px}
.row__conflict{grid-column:2 / -1}
.row__conflictIn{display:none;background:#F7E6E1;border:2px solid var(--vermil);border-radius:var(--r);
  padding:12px 14px;margin:0 0 20px;align-items:flex-start;gap:10px}
.row.has-conflict .row__conflictIn{display:flex}
.row__conflictIc{font-size:13px;color:var(--vermil);line-height:1.5;flex:none}
.row__conflictTx{font-size:13.5px;line-height:1.6}
.row__conflictTx b{color:var(--vermil-d)}
.row__drawer{display:grid;grid-template-rows:0fr;transition:grid-template-rows .42s var(--ease)}
.row.is-open .row__drawer{grid-template-rows:1fr}
.row__drawerIn{overflow:hidden}
.row__drawerPad{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(0,1fr);gap:32px;
  padding:0 0 0 92px;opacity:0;transform:translateY(-4px);
  transition:opacity .3s var(--ease) .06s,transform .3s var(--ease) .06s}
.row.is-open .row__drawerPad{padding-top:4px;padding-bottom:28px;opacity:1;transform:none}
.row__intro{font-size:15px;line-height:1.75;color:var(--ink-2);margin:0 0 16px;
  border-left:3px solid var(--vermil);padding-left:16px}
.row__note{background:var(--paper-2);border:1px solid var(--line);border-radius:var(--r);padding:16px}
.row__noteK{font-family:var(--mono);font-size:11px;letter-spacing:.16em;color:var(--ink-3);
  margin:0 0 8px;padding-bottom:6px;border-bottom:1px solid var(--line-soft)}
.row__noteP{font-family:var(--serif);font-size:15px;line-height:1.75;margin:0 0 12px}
.row__speaker{font-size:13.5px;line-height:1.6;color:var(--ink-2);margin:0}
.row__speaker b{color:var(--ink)}
.row__seed{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}
.seed{font-family:var(--mono);font-size:12px;letter-spacing:.06em;border:1px solid var(--line);
  border-radius:var(--r);background:var(--paper);padding:5px 9px;color:var(--ink-2)}

.empty{border:2px dashed var(--line);border-radius:var(--r);padding:40px 28px;margin-top:8px}
.empty__t{font-size:20px;font-weight:700;margin:0 0 8px}
.empty__p{font-size:15px;line-height:1.7;color:var(--ink-2);max-width:32em;margin:0 0 20px}

/* panel */
.panel{padding:32px 0 32px 24px;border-left:1px solid var(--line);position:sticky;top:88px}
.panel__head{display:flex;justify-content:space-between;align-items:baseline;gap:12px;
  border-bottom:2px solid var(--ink);padding-bottom:10px}
.panel__h{margin:0;font-size:20px;font-weight:700;letter-spacing:.02em}
.panel__count{font-family:var(--mono);font-size:12px;color:var(--ink-3);font-variant-numeric:tabular-nums}
.panel__clockline{display:flex;justify-content:space-between;align-items:baseline;gap:12px;
  padding:12px 0;border-bottom:1px solid var(--line)}
.panel__clocklabel{font-size:13px;color:var(--ink-2)}
.panel__clockval{font-family:var(--mono);font-size:14px;font-weight:700;font-variant-numeric:tabular-nums}
.panel__alert{border:2px solid var(--vermil);border-radius:var(--r);background:#F7E6E1;
  padding:14px;margin:16px 0 0}
.panel__alert-t{margin:0 0 10px;font-size:14px;font-weight:700;color:var(--vermil-d)}
.panel__alert-list{list-style:none;margin:0 0 10px;padding:0;display:flex;flex-direction:column;gap:8px}
.panel__alert-list li{font-size:13px;line-height:1.55;border-left:2px solid var(--vermil);padding-left:10px}
.panel__alert-hint{font-size:12.5px;line-height:1.55;color:var(--ink-2);margin:0}
.clist{list-style:none;margin:0;padding:0}
.citem{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding:14px 0;
  border-bottom:1px solid var(--line);align-items:start}
.citem.is-new{animation:rowIn .32s var(--ease) both}
.citem__no{font-family:var(--mono);font-size:11px;letter-spacing:.1em;color:var(--vermil);margin:0 0 4px}
.citem__t{font-size:14.5px;font-weight:600;line-height:1.4;margin:0 0 4px}
.citem__m{font-family:var(--mono);font-size:12px;color:var(--ink-3);margin:0;font-variant-numeric:tabular-nums}
.citem__x{width:44px;height:44px;flex:none;display:grid;place-items:center;background:transparent;
  border:1px solid var(--line);border-radius:var(--r);cursor:pointer;font-size:15px;color:var(--ink-3);
  transition:background-color .14s var(--ease),color .14s var(--ease),border-color .14s var(--ease)}
.citem__x:hover{background:var(--vermil);border-color:var(--vermil);color:#FFF8F4}
.clist__empty{border:1px solid var(--line);border-radius:var(--r);background:var(--paper-2);
  padding:22px 18px;margin-top:16px}
.clist__empty-t{font-size:16px;font-weight:700;margin:0 0 8px}
.clist__empty-p{font-size:13.5px;line-height:1.65;color:var(--ink-2);margin:0 0 16px}
.clist__empty-b{width:100%;justify-content:center}
.clist__empty-n{font-size:12px;line-height:1.55;color:var(--ink-3);margin:10px 0 0}
.panel__bye{margin-top:16px}
.panel__bye .btn{width:100%;justify-content:center}
.panel__foot{font-size:12.5px;line-height:1.6;color:var(--ink-3);margin:24px 0 0;
  padding-top:12px;border-top:1px solid var(--line)}

/* about */
.about{max-width:1440px;margin:72px auto 0;padding:0 24px}
.about__grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.5fr);gap:56px;
  border-top:2px solid var(--ink);padding-top:40px}
.about__h{margin:0;font-size:34px;line-height:1.25;font-weight:700;letter-spacing:.01em;max-width:12em}
.about__r p{font-size:16px;line-height:1.8;color:var(--ink-2);margin:0 0 20px;max-width:38em}
.about__meta{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:2px solid var(--ink);
  border-radius:var(--r);margin-top:32px;overflow:hidden}
.about__metaItem{padding:16px;border-right:1px solid var(--line);background:var(--paper-2);
  display:flex;flex-direction:column;gap:6px}
.about__metaItem:last-child{border-right:0}
.about__metaK{font-family:var(--mono);font-size:11px;letter-spacing:.14em;color:var(--ink-3)}
.about__metaV{font-size:14.5px;font-weight:600;line-height:1.4}

/* faq */
.faq{max-width:1440px;margin:72px auto 0;padding:0 24px}
.faq__h{font-size:26px;font-weight:700;margin:0 0 24px;padding-bottom:12px;
  border-bottom:2px solid var(--ink);letter-spacing:.02em}
.faq__grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}
.fq{padding:24px 24px 24px 0;border-bottom:1px solid var(--line)}
.fq:nth-child(2n){padding-left:24px;border-left:1px solid var(--line)}
.fq__q{font-size:16px;font-weight:700;margin:0 0 8px;line-height:1.5;display:flex;gap:10px}
.fq__q span{font-family:var(--mono);font-size:13px;color:var(--vermil);flex:none;
  font-variant-numeric:tabular-nums}
.fq__a{font-size:14.5px;line-height:1.7;color:var(--ink-2);margin:0}

/* foot */
.foot{max-width:1440px;margin:72px auto 0;padding:0 24px}
.foot__grid{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.4fr) minmax(0,1.1fr);
  gap:40px;border-top:2px solid var(--ink);padding:32px 0}
.foot__brand{font-size:17px;font-weight:700;margin:0 0 6px;letter-spacing:.08em}
.foot__k{font-family:var(--mono);font-size:11px;letter-spacing:.16em;color:var(--vermil);margin:0 0 8px}
.foot__p{font-size:13.5px;line-height:1.7;color:var(--ink-2);margin:0}
.foot__bar{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  border-top:1px solid var(--line);padding:16px 0 44px;font-family:var(--mono);font-size:11.5px;
  letter-spacing:.14em;color:var(--ink-3)}

/* dock — 仅窄屏显示 */
.dock{position:fixed;left:0;right:0;bottom:0;z-index:30;
  padding:12px 16px calc(12px + env(safe-area-inset-bottom));
  background:rgba(245,241,233,.94);border-top:2px solid var(--ink);
  display:flex;align-items:center;gap:12px}
@supports (backdrop-filter:blur(10px)){.dock{backdrop-filter:blur(10px)}}
.dock__main{flex:1;display:flex;align-items:center;gap:10px;background:var(--vermil);color:#FFF8F4;
  border:2px solid var(--ink);border-radius:var(--r);padding:12px 16px;min-height:52px;
  cursor:pointer;font-size:15px;font-weight:600;transition:transform .14s var(--ease)}
.dock__main:active{transform:scale(.98)}
.dock__n{font-family:var(--mono);font-size:14px;font-weight:700;background:#FFF8F4;color:var(--vermil);
  min-width:24px;text-align:center;padding:1px 6px;border-radius:2px;font-variant-numeric:tabular-nums}
.dock__hint{margin-left:auto;font-family:var(--mono);font-size:12px;letter-spacing:.1em}
.dock__cnf{font-size:12.5px;color:var(--ok);font-weight:600;padding-right:4px}

/* toast */
.toast{position:fixed;left:24px;bottom:24px;z-index:40;display:flex;align-items:flex-start;gap:10px;
  max-width:min(420px,calc(100vw - 48px));background:var(--ink);color:var(--paper);border-radius:var(--r);
  padding:14px 16px;box-shadow:6px 6px 0 var(--vermil);font-size:13.5px;line-height:1.6;
  animation:toastIn .3s var(--ease) both}
.toast__ic{color:var(--vermil);flex:none;font-size:12px;line-height:1.6}
@keyframes toastIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
@keyframes glowPulse{0%,100%{background-color:var(--paper-2)}50%{background-color:var(--paper-3)}}
.citem.glow{animation:glowPulse 1.1s var(--ease) 1}

/* ============ 响应式 ============ */
@media (min-width:821px){ .dock{display:none !important} }

@media (max-width:1100px){
  .stage{grid-template-columns:minmax(0,188px) minmax(0,1fr)}
  .panel{grid-column:1 / -1;border-left:0;border-top:2px solid var(--ink);padding:32px 0;position:static}
}
@media (max-width:900px){
  .hero__grid{grid-template-columns:1fr;gap:36px}
  .hero{padding-top:32px}
  .daystrip{grid-template-columns:repeat(3,minmax(0,1fr))}
  .daystrip__note{grid-column:1 / -1;border-top:1px solid var(--line)}
  .about__grid{grid-template-columns:1fr;gap:24px}
  .about__meta{grid-template-columns:repeat(2,minmax(0,1fr))}
  .about__metaItem:nth-child(2){border-right:0}
  .about__metaItem:nth-child(-n+2){border-bottom:1px solid var(--line)}
  .foot__grid{grid-template-columns:1fr;gap:24px}
}
@media (max-width:820px){
  .topnav,.clock{display:none}
  .stage{grid-template-columns:1fr;margin-top:48px}
  .legend{border-right:0;border-bottom:1px solid var(--line);padding:24px 0;
    display:grid;grid-template-columns:1fr 1fr;gap:0 24px}
  .legend__block--note{grid-column:1 / -1;border-top:0;padding-top:0;margin-bottom:16px}
  .legend__reset{grid-column:1 / -1}
  .board{padding:24px 0}
  .panel{padding:24px 0 104px}
  .hero__title{font-size:clamp(72px,21vw,136px)}
  .row__head{grid-template-columns:56px minmax(0,1fr);gap:14px}
  .row__no{font-size:32px}
  .row__acts{flex-direction:row;grid-column:1 / -1;margin-top:14px}
  .row__acts .row__btn{flex:1}
  .board__colhead{grid-template-columns:56px minmax(0,1fr)}
  .ch--act{display:none}
  .row__drawerPad{grid-template-columns:1fr;gap:20px;padding-left:70px}
  .row__conflict{grid-column:1 / -1}
  .row.has-conflict{margin-left:0;padding-left:0}
  .faq__grid{grid-template-columns:1fr}
  .fq{padding:20px 0 !important;border-left:0 !important}
  .toast{left:16px;right:16px;bottom:92px;max-width:none}
  .about,.faq,.foot,.hero,.stage,.ticker__inner,.topbar{padding-left:20px;padding-right:20px}
  .tk-hide{display:none}
}
@media (max-width:460px){
  .legend{grid-template-columns:1fr}
  .daystrip{grid-template-columns:1fr}
  .daystrip__item{border-right:0;border-bottom:1px solid var(--line);flex-direction:row;
    align-items:baseline;justify-content:space-between;gap:10px}
  .daystrip__item:last-of-type{border-bottom:0}
  .hero__title{font-size:clamp(60px,23vw,104px)}
  .t2{text-shadow:2px 2px 0 var(--ink)}
  .about__meta{grid-template-columns:1fr}
  .about__metaItem{border-right:0;border-bottom:1px solid var(--line)}
  .about__metaItem:last-child{border-bottom:0}
  .row__drawerPad{padding-left:0}
  .hero__cta .btn{width:100%;justify-content:center}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.001ms !important;animation-iteration-count:1 !important;
    transition-duration:.001ms !important}
}

