/* 场间 FIELD NOTES · 概念样板交互
   仅本次页面有效；不使用 localStorage / sessionStorage。 */
(function () {
  'use strict';

  var SESSIONS = [
    { id:'s1', no:'01', day:'1', cat:'exhab', catLabel:'展览',
      title:'纸上留痕 · 手工纸与印刷样本展',
      start:'13:30', end:'15:00', place:'A 区 · 展位 A-1',
      intro:'把 200 多张同一种纸的不同批次摊开：打样、压纹、上墨、错位、返工。这场展览不解释工艺，只把过程本身摆出来——你会看到同一份设计稿在纸的湿度变化里，如何一次比一次更不像它原本的样子。',
      note:'做印刷的时候，最怕的不是印坏，是印得太干净。纸张有自己的脾气，你只能跟它商量。',
      noteBy:'主讲：黎昀（虚构）· 纸张与印刷实验', seeds:['纸张湿度','专色叠印','批次差异'] },
    { id:'s2', no:'02', day:'1', cat:'talk', catLabel:'对谈',
      title:'你说的高级，到底指什么',
      start:'15:30', end:'16:30', place:'B 区 · 圆桌 B-2',
      intro:'「高级」「有质感」「很干净」——这些词在评审会上出现得最多，也最难被追问。这场对谈把四个常见形容词拆成可观察的关系：比例、材质、密度、留白。谈的不是品味高低，是判断能不能被说出来。',
      note:'如果一句话里出现了三个形容词，通常说明你还没想清楚要留什么、去什么。',
      noteBy:'主讲：沈默、周禾（虚构）· 设计评论与教学', seeds:['形容词拆解','评审语言','判断力'] },
    { id:'s3', no:'03', day:'2', cat:'work', catLabel:'工作坊',
      title:'三次打样：从稿子到成品',
      start:'10:00', end:'12:30', place:'C 区 · 工坊 C-1',
      intro:'两小时半，只做一件事：把一份稿子打样三次。第一次照原样印，第二次换纸，第三次换色序。带走的是三份实物和一份失败记录——大多数人的第三次反而最难看，这也是要讲的。',
      note:'你们会恨第一版。但请留着它，它是唯一没有被我影响过的一版。',
      noteBy:'主带：程岚（虚构）· 印前与色彩管理', seeds:['打样','色序','留样对比'] },
    { id:'s4', no:'04', day:'2', cat:'exhab', catLabel:'展览',
      title:'网格之下 · 版面结构档案',
      start:'12:00', end:'13:30', place:'A 区 · 展位 A-3',
      intro:'把三十年的版面稿叠在一起，能看见同一套网格如何被反复破开。展场按「守—破—重建」排序，每一组都留了原始线框与最终成品的对照。看的是结构，不是风格。',
      note:'网格不是限制，是让你知道自己在偏离什么。没有网格的破格，只是乱。',
      noteBy:'主讲：柯岩（虚构）· 版面与信息设计', seeds:['栅格','破格依据','对照陈列'] },
    { id:'s5', no:'05', day:'2', cat:'talk', catLabel:'对谈',
      title:'看展的人在想什么',
      start:'15:00', end:'16:15', place:'B 区 · 圆桌 B-1',
      intro:'把观众当研究对象而不是受众。这场对谈放三段现场观察记录：人们在哪里停留、在哪里加速走过、在哪个展签前反复回头。讨论的是展览动线，也是设计如何被真正看见。',
      note:'我们跟踪了一位观众 40 分钟，他在一幅画前站了 11 秒——大部分时间花在找下一个展签。',
      noteBy:'主讲：闻笛（虚构）· 展览观察与观众研究', seeds:['观看动线','停留时长','展签密度'] },
    { id:'s6', no:'06', day:'3', cat:'work', catLabel:'工作坊',
      title:'带走一份小版式',
      start:'11:00', end:'12:30', place:'C 区 · 工坊 C-2',
      intro:'一小时半，用给定的一页内容排出六种版式，全部只用黑白与一种专色。限制是刻意的：颜色被拿走以后，剩下的只有比例、层级和对齐——也正是最难练的部分。',
      note:'把六版都排完再选。第一版通常是你最顺手的那一版，也就是你上一件作品。',
      noteBy:'主带：苏白（虚构）· 视觉设计与教学', seeds:['单色限制','层级','对齐关系'] }
  ];

  var FAQ = [
    ['需要提前做功课吗？','不需要。六场都按「15 分钟进入状态」设计，前段会交代背景。展览可随时进出，对谈与工作坊建议整场参加。'],
    ['展位 A / B / C 分别在哪？','A 区为展位区，B 区为圆桌区，C 区为工坊区，三区步行 4 至 6 分钟。此处为概念示意，不代表真实场地。'],
    ['为什么会提示时间冲突？','部分场次时段刻意留有重叠，用来演示冲突提醒。重叠不会被禁止加入，只在观展单与对应行上标出。'],
    ['观展单会被保存吗？','不会。它只存在于当前页面的这次浏览中，刷新即清空，不写入本地存储，也不会发送到任何地方。'],
    ['可以购票或报名吗？','不可以。本页不提供购票、报名、支付或名额服务，所有场次信息均为概念示例。'],
    ['三日一共多少时长？','六场合计 8 小时 30 分。若全部加入，周五与周六各会出现一处时段重叠。']
  ];

  var elRows = document.getElementById('rows');
  var elEmpty = document.getElementById('empty');
  var elBoardStatus = document.getElementById('boardStatus');
  var elCartList = document.getElementById('cartList');
  var elCartEmpty = document.getElementById('cartEmpty');
  var elCartBye = document.getElementById('cartBye');
  var elCartCount = document.getElementById('cartCount');
  var elCartTopCount = document.getElementById('cartTopCount');
  var elTotalHours = document.getElementById('totalHours');
  var elConflictBox = document.getElementById('conflictBox');
  var elConflictN = document.getElementById('conflictN');
  var elConflictList = document.getElementById('conflictList');
  var elToast = document.getElementById('toast');
  var elToastTxt = document.getElementById('toastTxt');
  var elDock = document.getElementById('dock');
  var elDockCount = document.getElementById('dockCount');
  var elDockCnf = document.getElementById('dockCnf');
  var elClock = document.getElementById('clock');
  var elResetAll = document.getElementById('resetAll');
  var elEmptyReset = document.getElementById('emptyReset');
  var elLoadSample = document.getElementById('loadSample');
  var elClearCart = document.getElementById('clearCart');
  var elDockMain = document.getElementById('dockMain');
  var elJumpCart = document.getElementById('jumpCart');
  var elFaqGrid = document.getElementById('faqGrid');

  var state = { day:'all', cat:'all', cart:{}, open:{}, animId:null };
  var toastTimer = null, flashTimer = null, clockTimer = null;

  function pad(n){ return (n < 10 ? '0' : '') + n; }
  function mins(t){
    var p = t.split(':');
    return parseInt(p[0], 10) * 60 + parseInt(p[1], 10);
  }
  function fmtDur(m){ return Math.floor(m / 60) + ' 小时 ' + (m % 60) + ' 分'; }
  function byId(id){
    for (var i = 0; i < SESSIONS.length; i++) {
      if (SESSIONS[i].id === id) return SESSIONS[i];
    }
    return null;
  }
  function dayLabel(d){
    return d === '1' ? '10/17 周五' : (d === '2' ? '10/18 周六' : '10/19 周日');
  }
  function catClass(c){
    return c === 'talk' ? 'row__tag row__tag--talk'
         : c === 'work' ? 'row__tag row__tag--work' : 'row__tag';
  }
  function esc(s){
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function overlaps(a, b){
    return mins(a.start) < mins(b.end) && mins(b.start) < mins(a.end);
  }

  function computeConflicts(){
    var ids = Object.keys(state.cart), map = {}, pairs = [], i, j;
    for (i = 0; i < ids.length; i++) map[ids[i]] = [];
    for (i = 0; i < ids.length; i++) {
      for (j = i + 1; j < ids.length; j++) {
        var a = byId(ids[i]), b = byId(ids[j]);
        if (a && b && a.day === b.day && overlaps(a, b)) {
          map[a.id].push(b.id);
          map[b.id].push(a.id);
          pairs.push([a, b]);
        }
      }
    }
    return { map: map, pairs: pairs, ids: ids };
  }

  function visibleSessions(){
    return SESSIONS.filter(function(s){
      var okDay = state.day === 'all' || s.day === state.day;
      var okCat = state.cat === 'all' || s.cat === state.cat;
      return okDay && okCat;
    });
  }

  function renderRows(){
    var list = visibleSessions();
    var cf = computeConflicts();
    var html = '', i, k;

    for (i = 0; i < list.length; i++) {
      var s = list[i];
      var inCart = !!state.cart[s.id];
      var isOpen = !!state.open[s.id];
      var conflicts = cf.map[s.id] || [];
      var hasCF = inCart && conflicts.length > 0;
      var cfs = [];
      if (hasCF) {
        for (k = 0; k < conflicts.length; k++) {
          var o = byId(conflicts[k]);
          cfs.push(o.no + '「' + esc(o.title) + '」(' + o.start + '–' + o.end + ')');
        }
      }

      html += '<article class="row' + (isOpen ? ' is-open' : '') +
              (hasCF ? ' has-conflict' : '') + '" data-row="' + s.id + '">';
      html += '<div class="row__head">';
      html += '<div class="row__no" aria-hidden="true">' + s.no + '</div>';
      html += '<div class="row__body">';
      html += '<span class="' + catClass(s.cat) + '"><span class="row__tagDot" aria-hidden="true"></span>' +
              s.catLabel + '</span>';
      html += '<h3 class="row__title" id="t-' + s.id + '">' + esc(s.title) + '</h3>';
      html += '<div class="row__meta">';
      html += '<span>D' + s.day + ' · ' + dayLabel(s.day) + '</span>';
      html += '<span><b>' + s.start + '–' + s.end + '</b></span>';
      html += '<span>' + esc(s.place) + '</span>';
      html += '</div></div>';
      html += '<div class="row__acts">';
      html += '<button type="button" class="row__btn row__btn--add' + (inCart ? ' is-in' : '') +
              '" data-act="cart" data-id="' + s.id + '" aria-pressed="' + (inCart ? 'true' : 'false') + '">' +
              (inCart ? '<span class="k">✓</span> 已加入' : '<span class="k">＋</span> 加入观展单') + '</button>';
      html += '<button type="button" class="row__btn" data-act="toggle" data-id="' + s.id +
              '" aria-expanded="' + (isOpen ? 'true' : 'false') + '" aria-controls="d-' + s.id + '">' +
              (isOpen ? '收起 <span class="k">↑</span>' : '展开介绍 <span class="k">↓</span>') + '</button>';
      html += '</div></div>';

      if (hasCF) {
        html += '<div class="row__conflict"><div class="row__conflictIn">' +
                '<span class="row__conflictIc" aria-hidden="true">▲</span>' +
                '<span class="row__conflictTx"><b>时段重叠：</b>与 ' + cfs.join('、') +
                ' 重叠，无法完整参加两场。</span></div></div>';
      }

      html += '<div class="row__drawer" id="d-' + s.id + '" role="region" aria-label="' +
              esc(s.title) + ' 详情"><div class="row__drawerIn"><div class="row__drawerPad">';
      html += '<div><p class="row__intro">' + esc(s.intro) + '</p><div class="row__seed">';
      for (k = 0; k < s.seeds.length; k++) {
        html += '<span class="seed">#' + esc(s.seeds[k]) + '</span>';
      }
      html += '</div></div>';
      html += '<div class="row__note"><p class="row__noteK">讲者备注 · 展前预录</p>' +
              '<p class="row__noteP">「' + esc(s.note) + '」</p>' +
              '<p class="row__speaker"><b>' + esc(s.noteBy) + '</b></p></div>';
      html += '</div></div></div></article>';
    }

    elRows.innerHTML = html;
    if (list.length === 0) { elEmpty.hidden = false; } else { elEmpty.hidden = true; }
    elBoardStatus.textContent = '显示 ' + list.length + ' / ' + SESSIONS.length + ' 场';

    var nodes = elRows.querySelectorAll('.row');
    for (i = 0; i < nodes.length; i++) nodes[i].classList.remove('is-new');
    if (state.animId !== null) {
      for (i = 0; i < nodes.length; i++) {
        if (nodes[i].getAttribute('data-row') === state.animId) nodes[i].classList.add('is-new');
      }
      state.animId = null;
    }
    renderCart();
  }

  function renderCart(){
    var cf = computeConflicts();
    var n = cf.ids.length;
    elCartCount.textContent = String(n);
    elCartTopCount.textContent = String(n);
    elDockCount.textContent = String(n);

    var sorted = cf.ids.slice().sort(function(a, b){
      var A = byId(a), B = byId(b);
      if (A.day !== B.day) return A.day < B.day ? -1 : 1;
      return mins(A.start) - mins(B.start);
    });

    var total = 0, html = '', i;
    for (i = 0; i < sorted.length; i++) {
      var s = byId(sorted[i]);
      total += mins(s.end) - mins(s.start);
      var hasCF = (cf.map[s.id] || []).length > 0;
      html += '<li class="citem" data-citem="' + s.id + '"><div>';
      html += '<p class="citem__no">' + s.no + ' · ' + s.catLabel + (hasCF ? ' · 有重叠' : '') + '</p>';
      html += '<p class="citem__t">' + esc(s.title) + '</p>';
      html += '<p class="citem__m">' + dayLabel(s.day) + ' ' + s.start + '–' + s.end + '</p>';
      html += '</div><button type="button" class="citem__x" data-act="rm" data-id="' + s.id +
              '" aria-label="从观展单移除 ' + esc(s.title) + '">✕</button></li>';
    }
    elCartList.innerHTML = html;
    elTotalHours.textContent = fmtDur(total);
    if (n === 0) { elCartEmpty.hidden = false; elCartBye.hidden = true; }
    else { elCartEmpty.hidden = true; elCartBye.hidden = false; }

    if (cf.pairs.length > 0) {
      elConflictBox.hidden = false;
      elConflictN.textContent = String(cf.pairs.length);
      var ch = '';
      for (i = 0; i < cf.pairs.length; i++) {
        var p = cf.pairs[i];
        ch += '<li><b>' + p[0].no + '</b> ' + p[0].start + '–' + p[0].end + ' 与 <b>' + p[1].no +
              '</b> ' + p[1].start + '–' + p[1].end + ' 重叠，同属 D' + p[0].day + '。</li>';
      }
      elConflictList.innerHTML = ch;
    } else {
      elConflictBox.hidden = true;
      elConflictList.innerHTML = '';
    }
  }

  function toast(msg){
    elToastTxt.textContent = msg;
    elToast.hidden = false;
    elToast.style.animation = 'none';
    void elToast.offsetWidth;
    elToast.style.animation = '';
    if (toastTimer) window.clearTimeout(toastTimer);
    toastTimer = window.setTimeout(function(){ elToast.hidden = true; }, 3400);
  }

  function dockFlash(txt){
    elDockCnf.textContent = txt;
    if (flashTimer) window.clearTimeout(flashTimer);
    flashTimer = window.setTimeout(function(){ elDockCnf.textContent = ''; }, 1600);
  }

  function glowItem(id){
    var node = elCartList.querySelector('[data-citem="' + id + '"]');
    if (!node) return;
    node.classList.remove('glow');
    void node.offsetWidth;
    node.classList.add('glow');
    window.setTimeout(function(){ node.classList.remove('glow'); }, 1200);
  }

  elRows.addEventListener('click', function(ev){
    var btn = ev.target.closest ? ev.target.closest('button[data-act]') : null;
    if (!btn) return;
    var act = btn.getAttribute('data-act');
    var id = btn.getAttribute('data-id');
    var s = byId(id);
    if (!s) return;

    if (act === 'toggle') {
      if (state.open[id]) { delete state.open[id]; } else { state.open[id] = true; }
      state.animId = id;
      renderRows();
      return;
    }

    var adding = !state.cart[id];
    if (adding) { state.cart[id] = true; } else { delete state.cart[id]; }
    state.animId = id;
    renderRows();

    if (adding) {
      var ids = Object.keys(state.cart), others = [], i;
      for (i = 0; i < ids.length; i++) {
        if (ids[i] === id) continue;
        var o = byId(ids[i]);
        if (o && o.day === s.day && overlaps(s, o)) others.push(o);
      }
      if (others.length > 0) {
        toast('已加入 ' + s.no + '。与 ' + others[0].no + ' 时段重叠，观展单里已标出。');
      } else {
        toast('已加入 ' + s.no + '「' + s.title + '」');
      }
      glowItem(id);
      dockFlash('已加入');
    } else {
      toast('已移除 ' + s.no + '「' + s.title + '」');
      dockFlash('已移除');
    }
  });

  elCartList.addEventListener('click', function(ev){
    var btn = ev.target.closest ? ev.target.closest('button[data-act="rm"]') : null;
    if (!btn) return;
    var id = btn.getAttribute('data-id');
    var s = byId(id);
    if (!s) return;
    delete state.cart[id];
    state.animId = null;
    renderRows();
    toast('已移除 ' + s.no + '「' + s.title + '」');
    dockFlash('已移除');
  });

  var filters = document.querySelectorAll('.filt');
  function syncFilters(){
    for (var i = 0; i < filters.length; i++) {
      var kind = filters[i].getAttribute('data-kind');
      var val = filters[i].getAttribute('data-val');
      var on = state[kind] === val;
      if (on) { filters[i].classList.add('is-on'); } else { filters[i].classList.remove('is-on'); }
      filters[i].setAttribute('aria-pressed', on ? 'true' : 'false');
    }
  }
  for (var fi = 0; fi < filters.length; fi++) {
    filters[fi].addEventListener('click', function(){
      state[this.getAttribute('data-kind')] = this.getAttribute('data-val');
      state.animId = null;
      syncFilters();
      renderRows();
    });
  }

  elResetAll.addEventListener('click', function(){
    state.day = 'all'; state.cat = 'all';
    state.cart = {}; state.open = {}; state.animId = null;
    syncFilters();
    renderRows();
    toast('已清除筛选与观展单，回到 6 场全览。');
  });

  elEmptyReset.addEventListener('click', function(){
    state.day = 'all'; state.cat = 'all'; state.animId = null;
    syncFilters();
    renderRows();
  });

  elLoadSample.addEventListener('click', function(){
    state.cart = { s1: true, s3: true, s4: true };
    state.day = 'all'; state.cat = 'all'; state.animId = null;
    syncFilters();
    renderRows();
    toast('已载入 3 场示例（01 / 03 / 04）。03 与 04 时段重叠，冲突提醒已出现。');
  });

  elClearCart.addEventListener('click', function(){
    state.cart = {};
    state.animId = null;
    renderRows();
    toast('观展单已清空。');
  });

  elDockMain.addEventListener('click', function(){
    elToast.hidden = true;
    var p = document.getElementById('cartPanel');
    if (p && p.scrollIntoView) {
      p.scrollIntoView({ behavior: 'smooth', block: 'start' });
      p.setAttribute('tabindex', '-1');
      p.focus({ preventScroll: true });
    }
  });

  elJumpCart.addEventListener('click', function(){
    var p = document.getElementById('cartPanel');
    if (p && p.scrollIntoView) p.scrollIntoView({ behavior: 'smooth', block: 'start' });
  });

  var fh = '';
  for (var q = 0; q < FAQ.length; q++) {
    fh += '<div class="fq"><p class="fq__q"><span>' + pad(q + 1) + '</span>' + esc(FAQ[q][0]) +
          '</p><p class="fq__a">' + esc(FAQ[q][1]) + '</p></div>';
  }
  elFaqGrid.innerHTML = fh;

  function tick(){
    var d = new Date();
    elClock.textContent = pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
  }
  tick();
  clockTimer = window.setInterval(tick, 1000);

  syncFilters();
  renderRows();
})();
